/* Directly copied from 工具集/dist/entrance.js and app.js; icon paths from catalog.js. */
(()=>{
const toolPaths={"sparkles":"M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z","heart":"M12 21L3 12C-3 5 7-2 12 6c5-8 15-1 9 6z","star":"M12 2l3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1z","leaf":"M20 3C3 1-1 17 8 20c8 3 13-6 12-17z M5 21L16 8"};
function toolIcon(id,width=20,color='currentColor',style='line',height=width){const path=toolPaths[id]||toolPaths.sparkles;return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet"><path d="${path}" fill="none" stroke="${color}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
const toolVisibility = [{id:"studio",visible:true,order:0},{id:"palette",visible:true,order:1},{id:"cutout",visible:true,order:2},{id:"emoji",visible:true,order:3}];
function homeBackdrop(){return `<div class="home-atmosphere" aria-hidden="true"><div class="haze haze-purple"></div><div class="haze haze-teal"></div><div class="haze haze-gold"></div>${Array.from({length:22},(_,i)=>`<i class="ambient-star" style="--x:${(i*37+9)%100}%;--y:${(i*23+7)%100}%;--delay:${i*.61}s;--duration:${4+i%5}s"></i>`).join('')}<i class="ambient-meteor"></i><i class="ambient-meteor second"></i><i class="ambient-meteor third"></i><svg class="botanical-lines" viewBox="0 0 1200 800" preserveAspectRatio="xMidYMid slice"><g fill="none" stroke="currentColor" stroke-width="1.4"><path d="M-20 750Q130 610 100 420M88 575Q0 560 10 490Q90 505 88 575ZM101 517Q170 480 168 419Q98 433 101 517ZM55 661Q-10 640-20 578M100 465Q40 444 52 394Q106 407 100 465M1010 830Q1080 650 1190 540M1105 675Q1030 660 1050 602Q1118 612 1105 675ZM1140 620Q1210 640 1230 580Q1160 573 1140 620M1080 740Q1160 770 1170 702Q1096 685 1080 740M1138 155q-50-45-68 0q18 47 68 0q45-50 0-68q-47 18 0 68q50 45 68 0q-18-47-68 0q-45 50 0 68q47-18 0-68Z"/></g></svg></div>`;}
function toolCards(config=toolVisibility){const markup= `<div class="app-cards"><article class="app-choice icons-choice" data-tool-card="studio" tabindex="0" role="link" aria-label="进入轻图标"><div class="tool-art"><span>${toolIcon('sparkles',42,'#8B72DF')}</span><span>${toolIcon('heart',25,'#AE9CDC')}</span><span>${toolIcon('star',21,'#AE9CDC')}</span></div><span class="tool-category">图形 · 创作</span><h3>轻图标</h3><p>让想法，拥有自己的形状。</p><div class="tool-bottom"><span>图标生成与素材下载</span><button class="round-arrow" data-destination="studio" aria-label="进入轻图标">↗</button></div></article><article class="app-choice palette-choice" data-tool-card="palette" tabindex="0" role="link" aria-label="了解轻色卡"><div class="tool-art palette-art"><span></span><span></span><span></span></div><span class="tool-category">色彩 · 灵感</span><h3>轻色卡</h3><p>给灵感，配上一点颜色。</p><div class="tool-bottom"><span>敬请期待</span></div></article><article class="app-choice cutout-choice" data-tool-card="cutout" aria-disabled="true" aria-label="轻抠图，敬请期待"><div class="tool-art cutout-art"><span>${toolIcon('leaf',42,'#75A89B')}</span></div><span class="tool-category">影像 · 编辑</span><h3>轻抠图</h3><p>留下主角，让画面更自由。</p><div class="tool-bottom"><span>敬请期待</span></div></article><article class="app-choice emoji-choice" data-tool-card="emoji" tabindex="0" role="link" aria-label="了解轻表情"><div class="tool-art emoji-art" aria-hidden="true"><span class="emoji-face"><svg viewBox="0 0 72 72" width="72" height="72" fill="none"><circle cx="36" cy="36" r="29" fill="currentColor" fill-opacity=".14" stroke="currentColor" stroke-width="2"/><path class="emoji-eyes" d="M25 28v5m22-5v5" stroke="currentColor" stroke-width="4" stroke-linecap="round"/><path class="emoji-smile" d="M24 43q12 14 24 0" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><path d="m56 9 2-5m6 12 5-1" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span></div><span class="tool-category">表情 · 趣味</span><h3>轻表情</h3><p>把小情绪，变成有戏的表情。</p><div class="tool-bottom"><span>敬请期待</span></div></article></div>`;const cards=[...markup.matchAll(/<article[\s\S]*?<\/article>/g)].map(m=>m[0]);const shown=config.filter(c=>c.visible!==false).slice().sort((a,b)=>a.order-b.order).map(c=>cards.find(card=>card.includes(`data-tool-card="${c.id}"`))).filter(Boolean);return `<div class="app-cards" style="--app-count:${Math.max(1,Math.min(shown.length,4))}">${shown.join('')}</div>`;}
function home(config=toolVisibility){return `${homeBackdrop()}<section class="welcome"><span class="cover-kicker">SHIYU TOOLS</span><h1>拾隅工具</h1><p>轻图标、轻色卡、轻抠图与轻表情，都在这里。</p></section>${toolCards(config)}`;}
function bindToolCards(root,onOpen){root.querySelectorAll('[data-tool-card]:not([aria-disabled="true"])').forEach(card=>{card.onclick=event=>{if(event.target.closest('button'))return;onOpen(card.dataset.toolCard);};card.onkeydown=event=>{if(event.target!==card||!['Enter',' '].includes(event.key))return;event.preventDefault();onOpen(card.dataset.toolCard);};});}
function bind(root,onOpen){bindToolCards(root,onOpen);root.querySelectorAll('[data-destination]').forEach(button=>{button.onclick=()=>onOpen(button.dataset.destination);});}
window.ShiyuMaterialToolHome=Object.freeze({homeBackdrop,toolCards,home,bind});
})();
